def linked(digits):
    head = None
    for digit in reversed(digits):
        head = ListNode(digit, head)
    return head
def digits_of(head):
    out = []
    while head is not None and len(out) < 2_000:
        out.append(head.val)
        head = head.next
    return out
def sum_of(a, b):
    # Adds two digit lists (least significant first) and also checks that the inputs were left alone and the result is made of new nodes.
    first, second = linked(a), linked(b)
    result = add_two_numbers(first, second)
    if digits_of(first) != list(a) or digits_of(second) != list(b):
        raise AssertionError("the input lists must be left unchanged")
    given = set()
    for head in (first, second):
        while head is not None:
            given.add(id(head))
            head = head.next
    node = result
    while node is not None:
        if id(node) in given:
            raise AssertionError("the result must be a new list: it reuses a node of an input list")
        node = node.next
    return digits_of(result)

