class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def add_two_numbers(first, second):
    dummy = tail = ListNode()            # the result starts after this placeholder node
    carry = 0
    while first is not None or second is not None or carry:
        column = carry
        if first is not None:
            column += first.val
            first = first.next
        if second is not None:
            column += second.val
            second = second.next
        carry, digit = divmod(column, 10)
        tail.next = ListNode(digit)
        tail = tail.next
    return dummy.next
